{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"rent_increase_limits","lifecycle":"enacted","title":"Massachusetts ban on local rent control (Ch. 40P exception)","requirement":"No city or town may enact, maintain or enforce rent control of any kind. A city or town that accepts this chapter may adopt rent control regulation only on the stated conditions, including that owner participation becomes voluntary after six months.","key_value":null,"coverage_conditions":"Every city and town in Massachusetts; rent control is allowed only in a municipality that accepts this chapter, and may not apply to units owned by a person or entity holding fewer than ten rental units or with fair market rent above $400.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Rent control regulation may not apply to a rental unit owned by a person or entity owning fewer than ten rental units, or with fair market rent exceeding $400; adopting municipality must compensate owners from general funds"},"exemptions":"Units owned by a person or entity owning fewer than ten rental units; units with fair market rent exceeding $400. After six months from initial adoption, owners may decline to be subject to the regulation and their property is wholly unaffected.","penalty":null,"effective_date":null,"citation":"G.L. c. 40P, § 4","quoted_span":"No city or town may enact, maintain or enforce rent control of any kind, except that any city or town that accepts this chapter may adopt rent control regulation that provides:","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"just_cause_eviction","lifecycle":"enacted","title":"Ban on local rent control regulation of evictions and occupancy","requirement":"A city or town that adopts rent control under this chapter may not include regulation of occupancy, services, evictions, condominium conversion or removal of properties from that rent control.","key_value":null,"coverage_conditions":"Rent control regulation adopted by a city or town that accepts this chapter; excludes units owned by a person or entity holding fewer than ten rental units and units with fair market rent exceeding $400.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Applies to rent control regulation adopted by a city or town that accepts this chapter"},"exemptions":"Units owned by a person or entity owning fewer than ten rental units; units with fair market rent exceeding $400.","penalty":null,"effective_date":null,"citation":"G.L. c. 40P, § 4","quoted_span":"such regulation may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from such regulation, nor may such regulation apply to any rental unit that is owned by a person or entity owning less than ten rental units or that has a fair market rent exceeding $400","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
